_TAPE[0]["market"] = [["BUY_PRODUCT", "WHEAT", 30]]
_TAPE[1]["market"].insert(0, ["SELL", "WHEAT", 25])
# M2: turn-1 sell quantity chosen by the opponent's turn-0 wheat purchase (visible via its cash).
# Grid on seeds 1-6 both seats: opp bought ~53 -> sell 18 (+70k yuan800, +151k atakan);
# ~43 -> sell 24 (+119k strawhats); otherwise 25 (H32 default).
M2_SELL = {"big": 18, "mid": 24, "other": 25}


def _m2_class(obs):
    """Opponent's turn-0 wheat purchase, exact from the shared market inventory."""
    try:
        inv = obs["market"]["inventory"]["WHEAT"]
        mine = int(_TAPE[0]["market"][0][2])
        n = 10000 - int(inv) - mine - 1  # town center consumed 1 at step 0
        if n >= 48:
            return "big"
        if n >= 38:
            return "mid"
        return "other"
    except Exception:
        return "other"


def _m2_turn1(obs):
    act = _json.loads(_json.dumps(_TAPE[1]))
    act["market"][0] = ["SELL", "WHEAT", M2_SELL[_m2_class(obs)]]
    return act
